mapper.select:
select aw.workspace_id, aw.app_id, aw.workspace_name, aw.branch, aw.directory_path, aw.enabled
from application_workspaces aw
where aw.app_id = #{appId}
  and (
      exists (
          select 1 from application_members am
          where am.app_id = aw.app_id and am.deleted_at is null
            and (#{globalScope} = true or exists (
                select 1 from system_admin_team_members team
                where team.owner_user_id = #{ownerUserId}
                  and team.member_user_id = am.user_id and team.deleted_at is null
            ))
      )
      or exists (
          select 1 from personal_workspaces pw
          where pw.application_workspace_id = aw.workspace_id
            and (#{globalScope} = true or exists (
                select 1 from system_admin_team_members team
                where team.owner_user_id = #{ownerUserId}
                  and team.member_user_id = pw.user_id and team.deleted_at is null
            ))
      )
  )
order by aw.workspace_name, aw.workspace_id
